<?php $title=$title??'Module';require __DIR__.'/../layouts/header.php';?><div class="pagehead"><div><h1><?=App\Support\View::e($title)?></h1><p>Records currently available in this module.</p></div></div><div class="panel"><table><thead><tr><?php if(!empty($rows)):foreach(array_keys($rows[0]) as $h):?><th><?=App\Support\View::e($h)?></th><?php endforeach;endif;?></tr></thead><tbody><?php foreach($rows as $row):?><tr><?php foreach($row as $v):?><td><?=App\Support\View::e(is_scalar($v)?$v:json_encode($v))?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div><?php require __DIR__.'/../layouts/footer.php';?>